import { GEO } from './madrid-geodata.js';

// js/city-config.js
// Madrid centro spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/madrid-geodata.js (generated by tools/madrid/build.mjs from Ayuntamiento de Madrid IDEAM heights,
// Catastro footprints & OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), origin at Puerta del Sol (kilometre 0),
// no rotation. Phase 2 (the western half of the almendra central) spans the Manzanares (Príncipe Pío, Debod)
// east to Atocha: x ∈ [-1841.6, 1409.4], z ∈ [-1153.2, 1453.0], 8.45 km². The Manzanares is carved out of the
// land as real water (GEO.water), so the coast ring is the frame cut, not a river.
//
// NYC-only machinery (islands, bridges, piers, boroughs) is stubbed empty or far off-map so unedited
// importer code survives without inventing Manhattan; the Madrid config below feeds the rest from real data.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const CUT_Z = GEO.frame.cutZ;
// NYC-authored content (street furniture, park trees, subway entrances) has no place in Madrid: park it far
// north of the phase box, out of sight beyond the detail cut
const PARKED_Z = CUT_Z - 3000;

// ---------------------------------------------------------------------------------------------------------------------
// E-W / diagonal arterials (Alcalá, Gran Vía, Calle Mayor, ...): their real z & x-runs
//   [n, label, z, w, lanes, dir (+1 eastbound / -1 westbound / 0 two-way), hw, segs [[x0, x1, dir, w], ...]]
// ---------------------------------------------------------------------------------------------------------------------
const STREET_BY_NUMBER = new Map(GEO.streets.map((s) => [s[0], { label: s[1], z: s[2], w: s[3], lanes: s[4], dir: s[5], hw: s[6], segs: s[7] }]));
function streetZ(n) {
  const s = STREET_BY_NUMBER.get(n);
  if (s) return s.z;
  return PARKED_Z; // never interpolate fake streets into the middle of Sol
}

// ---------------------------------------------------------------------------------------------------------------------
// Avenues: real N-S corridors (Calle Preciados, Montera, Carretas, Sevilla, ...), x = weighted centreline,
// extents along z, per-stretch direction
//   [id, label, x, width, lanes, dir, hw, segs [{ z0, z1, dir, w, lanes, names }]]
// ---------------------------------------------------------------------------------------------------------------------
const ALL_AVENUES = GEO.avenues.map(([id, label, x, width, lanes, dir, hw, segs]) => ({
  id,
  x,
  name: label,
  short: label,
  dir,
  width, // curb-to-curb roadway (m)
  sidewalk: 4.0,
  lanes,
  hw: !!hw,
  minZ: Math.min(...segs.map((s) => s.z0)),
  maxZ: Math.max(...segs.map((s) => s.z1)),
  segs,
  hasMedian: false,
  isSecondary: false,
  splitByCentralPark: false
}));
const AVENUE_BY_ID = new Map(ALL_AVENUES.map((a) => [a.id, a]));
const avenueWarned = new Set();
const avenueX = (id) => {
  const a = AVENUE_BY_ID.get(String(id));
  if (!a) {
    if (!avenueWarned.has(id)) {
      avenueWarned.add(id);
      console.warn(`[city-config] no Madrid avenue "${id}"`);
    }
    return 999999; // keep distance comparisons sane instead of throwing
  }
  return a.x;
};
function avenueNameAt(ave, z) {
  if (!ave.segs) return ave.short;
  for (const s of ave.segs) {
    if (z < s.z0 - 30 || z > s.z1 + 30) continue;
    for (const [a, b, n] of s.names || []) if (z >= a - 30 && z <= b + 30) return n;
  }
  return ave.short;
}

// Core detail corridors (signal heads, crosswalk details, facades): the 7 most central-wide N-S streets
const aveLen = (a) => a.segs.reduce((s, g) => s + (g.z1 - g.z0), 0);
const boxCentre = { x: 225, z: -170 };
const AVENUES = [...ALL_AVENUES]
  .sort((p, q) => (aveLen(q) * q.width) / (1 + Math.hypot(q.x - boxCentre.x, (q.minZ + q.maxZ) / 2 - boxCentre.z)) -
    (aveLen(p) * p.width) / (1 + Math.hypot(p.x - boxCentre.x, (p.minZ + p.maxZ) / 2 - boxCentre.z)))
  .slice(0, 7)
  .sort((p, q) => p.x - q.x)
  .map((a) => ({ id: a.id, x: a.x, name: a.name, short: a.short, dir: a.dir, width: a.width, sidewalk: a.sidewalk }));
// Core E-W arterials (same detail layer for cross streets)
const coreLabel = (label, extra = {}) => {
  const s = GEO.streets.find((t) => t[1] === label);
  if (!s) return null;
  const seg = s[7].reduce((m, q) => (q[1] - q[0] > m[1] - m[0] ? q : m), s[7][0]);
  return { z: s[2], name: label, dir: s[5], width: s[3], sidewalk: 4.0, number: s[0], ...extra };
};
const STREETS = [
  coreLabel('Gran Vía', { isMajor: true }),
  coreLabel('Calle de Alcalá', { isMajor: true }),
  coreLabel('Calle Mayor', { isMajor: true }),
  coreLabel('Carrera de San Jerónimo', { isMajor: true }),
  coreLabel('Calle de Fuencarral')
].filter(Boolean);

// ---------------------------------------------------------------------------------------------------------------------
// Phase-1 bounds (the "island"): the city builds inside this box; beyond it is fog
// ---------------------------------------------------------------------------------------------------------------------
const CENTRAL_PARK_BOUNDS = { minX: 99999, maxX: 100000, minZ: 99999, maxZ: 100000 }; // no park; keep comparisons false

// Shoreline scanline over the phase box ring (same contract as the NYC bulkhead)
const MANHATTAN_COASTLINE = toPts(GEO.manhattan);
const SHORE = (() => {
  const step = 2;
  let z0 = Infinity;
  let z1 = -Infinity;
  for (const p of MANHATTAN_COASTLINE) {
    z0 = Math.min(z0, p.z);
    z1 = Math.max(z1, p.z);
  }
  z0 = Math.ceil(z0 / step) * step;
  const n = Math.floor((z1 - z0) / step) + 1;
  const west = new Float32Array(n).fill(NaN);
  const east = new Float32Array(n).fill(NaN);
  const P = MANHATTAN_COASTLINE;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[j];
    const b = P[i];
    if (a.z === b.z) continue;
    const lo = Math.min(a.z, b.z);
    const hi = Math.max(a.z, b.z);
    for (let k = Math.max(0, Math.ceil((lo - z0) / step)); k < n && z0 + k * step < hi; k++) {
      const z = z0 + k * step + 1e-3;
      if (z < lo || z >= hi) continue;
      const x = a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z);
      if (!(west[k] <= x)) west[k] = x;
      if (!(east[k] >= x)) east[k] = x;
    }
  }
  for (let k = 1; k < n; k++) if (Number.isNaN(west[k])) { west[k] = west[k - 1]; east[k] = east[k - 1]; }
  for (let k = n - 2; k >= 0; k--) if (Number.isNaN(west[k])) { west[k] = west[k + 1]; east[k] = east[k + 1]; }
  return { z0, step, n, west, east, z1 };
})();

/** West / east bound of the phase box at a given z */
function getIslandBoundsAtZ(z) {
  const f = (z - SHORE.z0) / SHORE.step;
  const k = Math.max(0, Math.min(SHORE.n - 2, Math.floor(f)));
  const t = Math.max(0, Math.min(1, f - k));
  return {
    westX: SHORE.west[k] + (SHORE.west[k + 1] - SHORE.west[k]) * t,
    eastX: SHORE.east[k] + (SHORE.east[k + 1] - SHORE.east[k]) * t
  };
}

// ---------------------------------------------------------------------------------------------------------------------
// The neutral spine the NYC code calls "Broadway": kept as a plain N-S line through the box so facade logic has
// something to compare against; Madrid's real diagonals live in ROADS/roadGraph
// ---------------------------------------------------------------------------------------------------------------------
const BROADWAY_LINE = toPts(GEO.broadway);
function getBroadwayX(z) {
  const L = BROADWAY_LINE;
  if (z <= L[0].z) return L[0].x;
  if (z >= L[L.length - 1].z) return L[L.length - 1].x;
  let lo = 0;
  let hi = L.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (L[mid].z <= z) lo = mid;
    else hi = mid;
  }
  const a = L[lo];
  const b = L[hi];
  return a.x + ((z - a.z) / Math.max(1e-6, b.z - a.z)) * (b.x - a.x);
}

// The river & water polygons (GEO.water: the Manzanares and Madrid Río, real OSM geometry, clipped to the frame).
// city-grid.js builds the ground deck with these as holes, so the channel is carved out of the city.
const MADRID_WATER = (GEO.water || []).map(toPts);
// Every land piece the deck is laid on: the phase box (GEO.landRings, [manhattan]) — the frame cut, not a shoreline
const LAND_RINGS = (GEO.landRings && GEO.landRings.length ? GEO.landRings : [GEO.manhattan]).map(toPts);

// Waterfront piers: Madrid centro has none — kept empty so pier code builds nothing
const WATERFRONT_PIERS = [];

// ---------------------------------------------------------------------------------------------------------------------
// Islands, boroughs & bridges: none in Madrid centro. Polygons are tiny rings far off-map (import-time code
// reads their bounds/lengths); bridges are empty arrays so no bridge meshes are built.
// ---------------------------------------------------------------------------------------------------------------------
const ROOSEVELT_ISLAND_POLYGON = [];
const GOVERNORS_ISLAND_POLYGON = [];
const RANDALLS_ISLAND_POLYGON = [];
const LIBERTY_ISLAND_POLYGON = [];
const ELLIS_ISLAND_POLYGON = [];
const MILL_ROCK_POLYGON = [];
const LIBERTY_STATUE_POS = { x: 80000, z: 80000 }; // out of sight: boroughs.js's statue builder is unconditional
const biggestRing = (rings) => rings.reduce((a, r) => (r.length > a.length ? r : a), rings[0]);
const NJ_SHORELINE_POLYGON = toPts(GEO.boroughs.newJersey[0]);
const BROOKLYN_POLYGONS = GEO.boroughs.brooklyn.map(toPts);
const QUEENS_POLYGONS = GEO.boroughs.queens.map(toPts);
const BRONX_POLYGONS = GEO.boroughs.bronx.map(toPts);
const STATEN_ISLAND_POLYGON = toPts(biggestRing(GEO.boroughs.statenIsland));
const LONG_ISLAND_POLYGONS = [toPts(biggestRing(GEO.boroughs.brooklyn)), toPts(biggestRing(GEO.boroughs.queens))];
const LONG_ISLAND_POLYGON = LONG_ISLAND_POLYGONS[1];
const BRONX_POLYGON = toPts(biggestRing(GEO.boroughs.bronx));
const UPPER_MANHATTAN_POLYGON = toPts(GEO.upperManhattan);
// Fog-horizon land bands, repositioned beyond the phase box (north & east)
const WESTCHESTER_POLYGON = [{ x: -9000, z: PARKED_Z + 400 }, { x: 9000, z: PARKED_Z + 900 }, { x: 9000, z: -60000 }, { x: -9000, z: -60000 }];
const NASSAU_POLYGON = [{ x: 12000, z: -9000 }, { x: 60000, z: -9000 }, { x: 60000, z: 9000 }, { x: 12000, z: 9000 }];

const EAST_RIVER_BRIDGES = [];
const OUTER_BRIDGES = [];

// ---------------------------------------------------------------------------------------------------------------------
// Streets database: every arterial from GEO.streets at its real z & extent (labels & the maps' search)
// ---------------------------------------------------------------------------------------------------------------------
const MAJOR_STREETS = new Set(['Gran Vía', 'Calle de Alcalá', 'Calle Mayor', 'Carrera de San Jerónimo', 'Calle de Fuencarral', 'Calle de Hortaleza', 'Calle de la Sal', 'Calle del Carmen']);
const ALL_STREETS = [];
for (const [n, label, z, w, lanes, dir, hw, segs] of GEO.streets) {
  const runs = segs.filter((g) => g[1] - g[0] > 30);
  if (!runs.length) continue;
  const westX = Math.min(...runs.map((g) => g[0]));
  const eastX = Math.max(...runs.map((g) => g[1]));
  const main = runs.reduce((m, g) => (g[1] - g[0] > m[1] - m[0] ? g : m), runs[0]);
  ALL_STREETS.push({
    number: n,
    name: label,
    short: label,
    z,
    isMajor: MAJOR_STREETS.has(label) || w >= 16,
    isTransverse: false,
    dir: MAJOR_STREETS.has(label) ? 0 : dir,
    width: w,
    lanes,
    hw: !!hw,
    westX,
    eastX,
    runs,
    splitByCentralPark: false
  });
}
ALL_STREETS.sort((a, b) => a.z - b.z);

// Named roads (the real centreline) — maps, labels & lookups
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name, raw: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));
// The Gran Vía canyon, from the real OSM carriageway geometry: the blocks it crosses get Madrid's taller profile
const GRAN_VIA_CORRIDOR = (() => {
  const runs = ROADS.filter((r) => r.name === 'Gran Vía');
  if (!runs.length) return null;
  let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity;
  for (const r of runs) {
    for (const p of r.pts) {
      x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x);
      z0 = Math.min(z0, p.z); z1 = Math.max(z1, p.z);
    }
  }
  const pad = 45; // half the avenue's facade-to-facade width (Gran Vía is ~35 m)
  return { x0: x0 - pad, x1: x1 + pad, z0: z0 - pad, z1: z1 + pad };
})();

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (merged building parcel slab) with its lot rectangles
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...], park: park share, parkName, rect, frames
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: Math.min(maxX - minX, maxZ - minZ) < 9
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
/** The block (curb island) under (x, z), or null on the roadway / outside the box */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// ---------------------------------------------------------------------------------------------------------------------
// Barrios of the phase box: the real administrative boundaries (GEO.barrios, from OSM admin_level 10/9) tested as
// polygons; GEO.districts (their bounding boxes, or coarse rects when the boundaries were not fetched) is the fallback
// ---------------------------------------------------------------------------------------------------------------------
const BARRIOS = (GEO.barrios || []).map((b) => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (let i = 0; i < b.ring.length; i += 2) {
    minX = Math.min(minX, b.ring[i]); maxX = Math.max(maxX, b.ring[i]);
    minZ = Math.min(minZ, b.ring[i + 1]); maxZ = Math.max(maxZ, b.ring[i + 1]);
  }
  return { name: b.name, poly: toPts(b.ring), cx: b.cx, cz: b.cz, minX, maxX, minZ, maxZ };
});
function districtAt(x, z) {
  const gv = GRAN_VIA_CORRIDOR;
  if (gv && x > gv.x0 && x < gv.x1 && z > gv.z0 && z < gv.z1) return 'Gran Vía';
  for (const b of BARRIOS) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (pointInPoly(b.poly, x, z)) return b.name;
  }
  for (const [name, x0, x1, z0, z1] of GEO.districts) {
    if (x >= x0 && x <= x1 && z >= z0 && z <= z1) return name;
  }
  return 'centro';
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap, heights from IDEAM where available)
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
// Plaza centres from the real square outlines, with fixed fallbacks
const plazaC = (name, fb) => {
  const p = (GEO.plazasMadrid || []).find((q) => q.name === name);
  if (!p) return fb;
  let x = 0, z = 0;
  for (let i = 0; i < p.ring.length; i += 2) { x += p.ring[i]; z += p.ring[i + 1]; }
  const n = p.ring.length / 2;
  return { x: x / n, z: z / n };
};
// Street-level arrivals shared by every travel mode. Heading 0 faces south (+z), PI north.
// Every landing sits on a real carriageway/plaza roadway, clear of building colliders, facing the sight it names.
const TELEPORT_LOCATIONS = {
  sol: { x: 0, z: 0, heading: Math.PI }, // on the square, facing Casa de la Panadería & the clock
  callao: { ...plazaC('Plaza de Callao', { x: -170, z: -245 }), heading: -2.25 }, // facing the Carrión building up Gran Vía
  granvia: { x: 28, z: -374, heading: -1.68 }, // on Gran Vía's roadway, facing down the canyon toward Callao
  cibeles: { x: 875, z: -265, heading: 1.25 }, // on the Cibeles roundabout, facing the Palacio de Cibeles
  alcala: { x: 760, z: -389, heading: Math.PI / 2 }, // by the army headquarters, facing east up Calle de Alcalá
  mayor: { x: -332, z: 196, heading: 2.61 }, // at the Toledo arch mouth, facing into the square
  opera: { x: -612, z: -140, heading: 2.14 }, // on Plaza de Oriente's edge street, facing the Teatro Real
  // Phase 2: the west half of the almendra. Every landing is on a real carriageway/plaza roadway clear of blocks and
  // of the river, facing the sight it names (verified by tests/teleports.test.cjs).
  debod: { x: -1205.9, z: -719.3, heading: 2.66 }, // on Calle del Profesor Martín Almagro Basch, facing the Templo de Debod
  palacio: { x: -791.5, z: -126.2, heading: -1.61 }, // on Plaza de Oriente's roadway, facing the Palacio Real
  principepio: { x: -1345.6, z: -408.5, heading: 2.56 }, // on the Cuesta de San Vicente, facing Príncipe Pío
  atocha: { x: 1163, z: 1382.4, heading: 1.72 }, // on Calle de Méndez Álvaro, facing the Atocha station
  reinasofia: { x: 860.3, z: 1042.9, heading: -2.23 } // on the Plaza del Emperador Carlos V, facing the Reina Sofía
};
const site = (name) => LANDMARK_SITES[name];
// Map pins & place names (the old NYC_LANDMARKS contract, with Madrid places)
const NYC_LANDMARKS = [
  ['sol', 'Puerta del Sol', 'Sol', 'Sol'],
  ['callao', 'Plaza de Callao', 'Callao', 'Gran Vía'],
  ['granvia', 'Gran Vía', 'Gran Vía', 'Gran Vía'],
  ['cibeles', 'Plaza de Cibeles', 'Cibeles', 'Cibeles'],
  ['alcala', 'Puerta de Alcalá', 'P. de Alcalá', 'Jerónimos'],
  ['mayor', 'Plaza Mayor', 'Plaza Mayor', 'Austrias'],
  ['opera', 'Teatro Real', 'Teatro Real', 'Ópera'],
  ['debod', 'Templo de Debod', 'Debod', 'Moncloa'],
  ['palacio', 'Palacio Real', 'Palacio Real', 'Palacio'],
  ['principepio', 'Príncipe Pío', 'P. Pío', 'Palacio'],
  ['atocha', 'Estación de Atocha', 'Atocha', 'Atocha'],
  ['reinasofia', 'Museo Reina Sofía', 'Reina Sofía', 'Embajadores']
].map(([id, name, short, district]) => {
  const t = TELEPORT_LOCATIONS[id] || { x: 0, z: 0 };
  return { id, name, short, x: t.x, z: t.z, district };
});

const ISLAND_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of MANHATTAN_COASTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();

// Legacy midtown landmark block registry: nothing reserved
const LANDMARK_BLOCKS = new Set();

/**
 * Buildable footprint of the (col, row) detail cell between AVENUES[col..col+1] and STREETS[row..row+1].
 * Only used by landmark code that places authored models on the old midtown grid; Madrid's landmarks
 * stand on their real lots (LANDMARK_SITES).
 */
function getBlockBounds(col, row) {
  const westAve = AVENUES[col];
  const eastAve = AVENUES[col + 1];
  const northSt = STREETS[row];
  const southSt = STREETS[row + 1];
  const minX = westAve.x + westAve.width * 0.5 + westAve.sidewalk;
  const maxX = eastAve.x - eastAve.width * 0.5 - eastAve.sidewalk;
  const minZ = northSt.z + northSt.width * 0.5 + northSt.sidewalk;
  const maxZ = southSt.z - southSt.width * 0.5 - southSt.sidewalk;
  return {
    col, row, minX, maxX, minZ, maxZ,
    cx: (minX + maxX) * 0.5,
    cz: (minZ + maxZ) * 0.5,
    width: maxX - minX,
    depth: maxZ - minZ,
    sidewalkMinX: westAve.x + westAve.width * 0.5,
    sidewalkMaxX: eastAve.x - eastAve.width * 0.5,
    sidewalkMinZ: northSt.z + northSt.width * 0.5,
    sidewalkMaxZ: southSt.z - southSt.width * 0.5
  };
}

/**
 * Exact street / landmark name at any world (x, z): nearest roads of the real street centreline
 */
function getLocationLabel(x, z) {
  for (const lm of NYC_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 90) {
      const near = nearestRoads(x, z, 120).filter((r) => r.road.name);
      const ave = near.find((r) => !r.horizontal);
      const st = near.find((r) => r.horizontal);
      return `${lm.name}${ave || st ? ` · ${(ave || st).road.name}` : ''}`;
    }
  }
  const near = nearestRoads(x, z, 160).filter((r) => r.road.name);
  const ave = near.find((r) => !r.horizontal);
  const st = near.find((r) => r.horizontal);
  if (ave && st) return `${ave.road.name} & ${st.road.name}`;
  if (ave || st) return (ave || st).road.name;
  if (near.length) return near[0].road.name;
  const d = districtAt(x, z);
  return d === 'centro' ? 'Madrid Centro' : d;
}

/**
 * A point authored on the old NYC grid: Madrid has none of that content — park it far north of the box
 * (the sim keeps its authored street-furniture lists but nothing visible lands in the city)
 */
const fromOldFrame = (x, z) => ({ x: x * 0.8, z: PARKED_Z - z * 0.5 });

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for avenue or cross street traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside avenue (or cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

